    select 
        unSubmitNum,
        total,
        (case total

            when 0 THEN 0
            else ROUND((1-(unSubmitNum/total))*100,2) end)as rate,
        pageType
        from(

            select
                count(temp.SEND_STATUS) as total,
                nvl(sum(temp.lateNums),0) as unSubmitNum,
                '1' as pageType
                from(
                    select
                        case when ces.SEND_STATUS != #{nosubmit}  
                              and ces.CHB_SUBMIT_DEADLINE < ces.SUBMIT_TIME then 1  
